<!-- Simple white scroll-to-top button -- no growing progress ring. #pcScrollIndicator
     and the .is-visible toggle stay bare, driven by initScrollIndicator() in main.js. -->
<button type="button" id="pcScrollIndicator" class="tw-group tw-fixed tw-bottom-4 tw-right-4 tw-z-[1035] tw-flex tw-h-11 tw-w-11 tw-appearance-none tw-invisible tw-translate-y-2 tw-cursor-pointer tw-items-center tw-justify-center tw-rounded-full tw-border tw-border-solid tw-border-black/10 tw-bg-white tw-p-0 tw-opacity-0 tw-shadow-[0_8px_24px_rgba(28,20,16,0.12)] tw-transition-all tw-duration-300 hover:tw-shadow-[0_10px_28px_rgba(28,20,16,0.18)] focus-visible:tw-outline focus-visible:tw-outline-2 focus-visible:tw-outline-offset-2 focus-visible:tw-outline-powerlight md:tw-bottom-6 md:tw-right-6 [&.is-visible]:tw-visible [&.is-visible]:tw-translate-y-0 [&.is-visible]:tw-opacity-100 motion-reduce:tw-transition-none" aria-label="Scroll to top">
  <svg class="tw-h-4 tw-w-4 tw-text-power tw-transition-transform tw-duration-200 group-hover:-tw-translate-y-0.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.25" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
    <path d="M12 19V5M5 12l7-7 7 7"/>
  </svg>
</button>
